import sys, json, os, subprocess, signal

# ONE PROGRAM RUN IN A PROJECTION (GH #905, OR-FJ-G2). `./mat` hands over an
# argv it has already checked against `exec_allow` and the directory it laid
# out; this cell starts the program there WITHOUT a shell, with an environment
# of exactly three variables, under a time cap, and answers with the exit code
# and the last 8 KiB of each output stream. It never reads or writes a file of
# the workspace itself -- that is `./mat`'s scan afterwards.
#
# The sandbox of this cell is the program's sandbox (the child inherits it):
# no network, write access to `base_path` alone (granted by the owner's
# override, none in the template). A program that writes anywhere else fails
# at the kernel, not at a check here.
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}

TAIL_BYTES = 8192
DEFAULT_CAP_MS = 600000
KILL_GRACE_S = 5


# ================================================================ PURE HALF
def tail(data, n=TAIL_BYTES):
    """The last `n` bytes of a stream as text."""
    if not isinstance(data, (bytes, bytearray)):
        data = str(data or "").encode("utf-8", "replace")
    return bytes(data[-n:]).decode("utf-8", "replace")


def cap_ms(asked, cap):
    """The time cap of one run: the caller's `timeout_ms`, never above the
    cell's `exec_timeout_ms` (a caller cannot lift the owner's cap)."""
    try:
        c = int(cap)
    except Exception:
        c = DEFAULT_CAP_MS
    if c <= 0:
        c = DEFAULT_CAP_MS
    try:
        a = int(asked)
    except Exception:
        return c
    return c if a <= 0 else min(a, c)


def run_env(path, home, base):
    """The whole environment of the program: PATH, HOME and LANG, nothing
    inherited from the colony (no key, no token reaches a tool)."""
    return {"PATH": str(path or "/usr/local/bin:/usr/bin:/bin"),
            "HOME": str(home or base), "LANG": "C.UTF-8"}


def under(base, cwd):
    """Whether `cwd` is a directory strictly below `base`."""
    b = os.path.normpath(str(base or ""))
    c = os.path.normpath(str(cwd or ""))
    return b.startswith("/") and b != "/" and c.startswith(b + "/")


# ================================================================ RUN
def answer(payload):
    body = {"ok": True, "messages": []}
    body.update(payload)
    body["header"] = {"route": "ran", "op_id": str(hop.get("op_id") or "")}
    return body


def refuse(code, message):
    return answer({"ok": False, "error": {"code": code, "message": message}})


if str(hop.get("route") or "") != "in_run":
    sys.stderr.write("projection/run: unknown lane %r -- dropped\n" % hop.get("route"))
    print("[]")
    sys.exit(0)

base = str(P.get("base_path") or "")
argv = d.get("argv")
cwd = str(d.get("cwd") or "")
if not isinstance(argv, list) or not argv or not all(isinstance(x, str) and x for x in argv):
    out = refuse("bad_request", "argv is a list of strings")
elif (not under(base, cwd) or not os.path.isdir(cwd)
      or not under(os.path.realpath(base), os.path.realpath(cwd))):
    out = refuse("bad_path", "the run directory must lie below base_path")
else:
    cap = cap_ms(d.get("timeout_ms"), P.get("exec_timeout_ms", DEFAULT_CAP_MS))
    env = run_env(P.get("env_path"), P.get("env_home"), base)
    try:
        child = subprocess.Popen(argv, cwd=cwd, env=env, stdin=subprocess.DEVNULL,
                                 stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                 start_new_session=True, close_fds=True)
    except (OSError, ValueError) as e:
        out = refuse("exec_failed", "%s: %s" % (argv[0], e))
    else:
        try:
            so, se = child.communicate(timeout=cap / 1000.0)
            code = child.returncode
        except subprocess.TimeoutExpired:
            # the whole process group: a tool that forked must not outlive
            # its run
            try:
                os.killpg(child.pid, signal.SIGKILL)
            except OSError:
                child.kill()
            try:
                so, se = child.communicate(timeout=KILL_GRACE_S)
            except subprocess.TimeoutExpired:
                so, se = b"", b""
            code = "timeout"
        out = answer({"exit": code, "out_tail": tail(so), "err_tail": tail(se)})
print(json.dumps([out]))
